package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.ByteBuffer;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate3Test {

  @Test
  void positionReflectsReadsAndExplicitSeeks() throws Exception {
    ByteArraySeekableByteChannel channel =
        new ByteArraySeekableByteChannel(new byte[] {1, 2, 3, 4, 5, 6});

    assertEquals(0L, channel.position());

    channel.read(ByteBuffer.allocate(4));
    assertEquals(4L, channel.position());

    channel.position(2);
    assertEquals(2L, channel.position());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate4Test {

  @Test
  void positionAcceptsBoundaryValuesAndRejectsOutOfRange() throws Exception {
    ByteArraySeekableByteChannel channel =
        new ByteArraySeekableByteChannel(new byte[] {1, 2, 3});

    // Lower boundary: 0 is valid
    SeekableByteChannel result = channel.position(0L);
    assertSame(channel, result);
    assertEquals(0L, channel.position());

    // Upper boundary: Integer.MAX_VALUE is valid
    channel.position((long) Integer.MAX_VALUE);
    assertEquals((long) Integer.MAX_VALUE, channel.position());
    assertEquals(-1, channel.read(ByteBuffer.allocate(1)));

    // Just outside the boundaries is invalid
    assertThrows(IllegalArgumentException.class, () -> channel.position(-1L));
    assertThrows(
        IllegalArgumentException.class, () -> channel.position((long) Integer.MAX_VALUE + 1L));

    // Failed calls must not change the position
    assertEquals((long) Integer.MAX_VALUE, channel.position());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate5Test {

  @Test
  void positionReturnsSameChannelAllowingChaining() throws Exception {
    ByteArraySeekableByteChannel channel =
        new ByteArraySeekableByteChannel(new byte[] {1, 2, 3, 4, 5});

    SeekableByteChannel returned = channel.position(2);

    assertSame(channel, returned);
    assertEquals(2L, returned.position());

    ByteBuffer buf = ByteBuffer.allocate(2);
    int n = channel.position(1).read(buf);
    assertEquals(2, n);
    assertEquals(2, buf.get(0));
    assertEquals(3, buf.get(1));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.ByteBuffer;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate6Test {

  @Test
  void readAtExactEndOfDataReturnsEndOfStream() throws Exception {
    byte[] data = new byte[] {1, 2, 3};
    ByteArraySeekableByteChannel channel = new ByteArraySeekableByteChannel(data);

    ByteBuffer first = ByteBuffer.allocate(3);
    assertEquals(3, channel.read(first));
    assertEquals(3L, channel.position());

    ByteBuffer second = ByteBuffer.allocate(4);
    assertEquals(-1, channel.read(second));
    assertEquals(0, second.position());

    channel.position(data.length);
    assertEquals(-1, channel.read(ByteBuffer.allocate(1)));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.ByteBuffer;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate7Test {

  @Test
  void readFromNonZeroPositionReturnsOnlyRemainingBytes() throws Exception {
    byte[] data = {1, 2, 3, 4, 5};
    ByteArraySeekableByteChannel channel = new ByteArraySeekableByteChannel(data);
    channel.position(2);

    ByteBuffer dst = ByteBuffer.allocate(10);
    int read = channel.read(dst);

    assertEquals(3, read);
    assertEquals(5L, channel.position());
    assertEquals(3, dst.position());
    byte[] got = new byte[3];
    dst.flip();
    dst.get(got);
    assertArrayEquals(new byte[] {3, 4, 5}, got);
    assertEquals(-1, channel.read(ByteBuffer.allocate(4)));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.ByteBuffer;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate8Test {

  @Test
  void readAtEndReturnsMinusOne() throws Exception {
    ByteArraySeekableByteChannel channel =
        new ByteArraySeekableByteChannel(new byte[] {1, 2, 3});
    ByteBuffer buf = ByteBuffer.allocate(10);

    assertEquals(3, channel.read(buf));
    assertEquals(-1, channel.read(ByteBuffer.allocate(4)));

    channel.position(3);
    assertEquals(-1, channel.read(ByteBuffer.allocate(4)));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.ByteBuffer;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate9Test {

  @Test
  void sizeReturnsDataLengthAndIsIndependentOfPosition() throws Exception {
    ByteArraySeekableByteChannel channel =
        new ByteArraySeekableByteChannel(new byte[] {1, 2, 3, 4, 5});
    assertEquals(5L, channel.size());

    channel.read(ByteBuffer.allocate(2));
    assertEquals(5L, channel.size());

    ByteArraySeekableByteChannel empty = new ByteArraySeekableByteChannel(null);
    assertEquals(0L, empty.size());
  }
}

